// Data for the Foundation/Motion pages — from tokens/source/motion.json (GENERATED by scripts/build-motion.mjs
// from the Figma "Motion" collection). Docs and tokens come from the same file, so they can't drift apart.
import data from '../../../tokens/source/motion.json';

export type ScaleToken = {
  figma: string; css: string; kind: 'duration' | 'easing'; type: string;
  value: number | string; out: string; description: string; usedBy: string[];
};
export type GroupToken = { figma: string; css: string; alias: string; aliasCss: string; out: string };
export type MotionGroup = {
  group: string; owners: string; level: 'atom' | 'molecule' | 'organism';
  exception?: boolean; look?: string; tokens: GroupToken[];
};

export const motionMeta = (data as any).meta as { file: string; fileKey: string; pulled: string; count: number };
export const scale = (data as any).scale as ScaleToken[];
export const groups = (data as any).groups as MotionGroup[];
export const durations = scale.filter(t => t.kind === 'duration');
export const easings = scale.filter(t => t.kind === 'easing');
export const componentTokenCount = groups.reduce((n, g) => n + g.tokens.length, 0);

// "Use for" text — the agreed plan (Trinity-motion-tokens-review-v2.md §2a)
export const USE_FOR: Record<string, string> = {
  'duration/instant': 'Reduced-motion value for movement; icon / text swap',
  'duration/fast': 'Hover, press and check colour changes — most interactions',
  'duration/default': 'Cards, table rows, toggle, sliders, menus and dropdowns opening, modals',
  'duration/medium': 'Expand / collapse, drawers, notifications, progress value',
  'duration/gentle': 'Spinner rotation (one full turn)',
  'duration/sustained': 'Spinner rotation under reduced motion',
  'easing/linear': 'Constant speed — spinner rotation',
  'easing/ease-out': 'Trinity’s default — hover, things entering, expanding',
  'easing/ease-in': 'Things leaving — menu, tooltip, modal, notification, banner close',
  'easing/ease-in-out': 'Toggle knob slide',
};

// CSS keyword → cubic-bezier control points (the CSS spec values), for the curve previews
export const CURVES: Record<string, [number, number, number, number]> = {
  linear: [0, 0, 1, 1],
  'ease-out': [0, 0, 0.58, 1],
  'ease-in': [0.42, 0, 1, 1],
  'ease-in-out': [0.42, 0, 0.58, 1],
};

// Which groups use a scale token (from the aliases) → "button, checkbox, chip…"
export const groupsUsing = (t: ScaleToken) =>
  [...new Set(t.usedBy.map(n => (n.startsWith('nav/') ? n.split('/').slice(0, 2).join('/') : n.split('/')[0])))];
